x_comment(x_EnglishLexiconMt,"The Mt for defining lexicon predicates specific to the english language. Define english words and their pos assertions in the appropriate mt -- #$GeneralEnglishMt, #$EnglishMt, or one of the national standards. See #$AmericanEnglishMt, #$BritishEnglishMt, #$CanadianEnglishMt, #$ScottishEnglishMt, #$IrishEnglishMt, #$SouthAfricanEnglishMt, #$AustralianEnglishMt, and #$NewZealandEnglishMt. Example: #$Blue-TheWord should be defined and have its pos information in the #$GeneralEnglishMt; #$Color-TheWord should be defined in the #$GeneralEnglishMt, but should have its #$singular assertions in the #$AmericanEnglishMt as \"color\" and in the #$BritishEnglishMt as \"colour\".  Note the relationships between the various mts.") :- x_cid(a65b1271ac3acb).
xc_microtheory(a65b1271ac3acb,x_EnglishLexiconMt).
